using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea.GameStates;

public abstract class NoTargetSelectionCastStateJoystickAction : NoTargetSelectionCastStateAction
{
	[SerializeField]
	private VoidEvent OnStartNoTargetSelectionCastStateJoystick;

	protected abstract void CastAction();

	protected virtual void HighlightTargets()
	{
	}

	public override void OnStartState()
	{
		base.OnStartState();
		base.inputManager.MoveActionInstanceToDicePlacementCastAction();
		OnStartNoTargetSelectionCastStateJoystick.Raise();
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			HighlightTargets();
		});
		if (base.actionInstance is RuneInstance)
		{
			base.actionInstance.ActionDroppedOnBattleActionCastSpace();
		}
	}

	public override void Execute(float d)
	{
		if (base.inputManager.GetSelectButtonUp())
		{
			if (base.actionInstance is RuneInstance)
			{
				(base.actionInstance as RuneInstance).ToggleOnDragCanvasLayerAndCamera(mainCamera: false);
			}
			CastAction();
		}
		if (base.inputManager.GetCancelButtonUp() && base.actionInstance is RuneInstance)
		{
			(base.actionInstance as RuneInstance).ToggleOnDragCanvasLayerAndCamera(mainCamera: false);
		}
		base.inputManager.GetCancelButtonUpCancelBattleAction(base.actionInstance);
	}
}
